entries[104045] = { ["name"] = "Schlaf", ["text"] = "60 Dämonischer Furor 30 Meter Reichweite\nWirken in 1.7 sek.\nMacht das Ziel müde und lässt es bis zu 20 Sek. lang einschlafen.\n\nSchlafeinschränkungen\nVerursachter Schaden kann den Schlaf unterbrechen. Auf ein Ziel begrenzt." }
