entries[104130] = { ["name"] = "Kettenblitzschlag", ["text"] = "350 Mana 30 Meter Reichweite\nWirken in 2.5 sek.\nTrifft einen Feind mit einem Blitzschlag, der auf einen in der Nähe befindlichen Feind überspringt. Der Zauber wirkt auf bis zu 5 Ziele und verursacht mit jedem zusätzlichen Ziel weniger Naturschaden." }
