entries[104135] = { ["name"] = "Dämonischer Zirkel: Beschwören", ["text"] = "40 Dämonischer Furor\nWirken in 0.5 sek.\nBeschwört einen dämonischen Zirkel zu Euren Füßen, der 6 Min. lang anhält. Es kann jeweils nur ein dämonischer Zirkel beschworen werden. [ Glyphe 'Auge von Kilrogg' : Wenn Ihr den Zauber 'Dämonischer Zirkel: Beschwören' wirkt, während Ihr ein Auge von Kilrogg kontrolliert, wird der Beschwörungskreis an der Position des Auges beschworen ]" }
entries[104136] = { ["name"] = "Dämonischer Zirkel: Teleport", ["text"] = "40 Dämonischer Furor 40 Meter Reichweite\nSpontanzauber 30 sek. Abklingzeit\nTeleportiert Euch zu Eurem dämonischen Zirkel und entfernt alle bewegungseinschränkenden Effekte. [ Seelenbrand: Dämonischer Zirkel: Teleport : Seelenbrand:\nErhöht das Bewegungstempo um 50% und macht Euch gegen Bewegungseinschränkungs- und Bewegungsunfähigkeitseffekte immun. Hält 8 Sek. lang an. ]" }
