entries[104205] = { ["name"] = "Dämonenansturm", ["text"] = "40 Meter Reichweite\nWirken in 0.6 sek.\nIllidan stürmt auf sein Ziel zu und fügt ihm 100% Waffenschaden zu." }
entries[104214] = { ["name"] = "Lunarer Schuss", ["text"] = "150 Meter Reichweite\nWirken in 2 sek.\nSchießt auf einen Gegner und verursacht so Arkanschaden." }
entries[104215] = { ["name"] = "Giftprobe liefern" }
entries[104220] = { ["name"] = "Lebenslinie", ["text"] = "45 Meter Reichweite\nSofort\nOpfert 2% Eurer gesamten Gesundheit, um Euren beschworenen Dämon alle 1 Sek. um 6% seiner gesamten Gesundheit zu heilen. Hält 6 Sek. lang an.\n[\nMachterfüllte Kanalisierung\nWenn dieser Zauber erneut gewirkt wird, bevor seine Effektdauer endet, wird die Effektdauer um 0.05 Sek. erhöht.\nBis zu 0-mal stapelbar. ] [ Seelenbrand: Lebenslinie : Seelenbrand:\nRegeneriert 140% mehr Gesundheit und verringert den erlittenen Schaden 10 Sek. lang um 30%. ]" }
entries[104221] = { ["name"] = "Manabarriere", ["text"] = "Sofort\nUmhüllt den Zaubernden mit einer mächtigen Barriere, die kontinuierlich jede verlorene Gesundheit auf Kosten des Manas des Zaubernden wieder auffrischt." }
entries[104223] = { ["name"] = "Fluch der Erschöpfung", ["text"] = "40 Meter Reichweite\nSofort\nVerringert das Bewegungstempo des Ziels 30 Sek. lang um 30%.\n\nFlüche\nEs kann pro Ziel immer nur jeweils ein Fluch des Hexenmeisters aktiv sein. [ Seelenbrand: Fluch : Seelenbrand:\nEuer Zauber 'Fluch der Erschöpfung' trifft alle Gegner im Umkreis von 15 Metern um Euer Ziel. ]" }
entries[104225] = { ["name"] = "Fluch der Elemente", ["text"] = "1 Combopunkt 40 Meter Reichweite\nSpontanzauber\nVerflucht das Ziel [ Glyphe 'Fluch der Elemente' : und 2 zusätzliche Ziele in der Nähe ], wodurch der erlittene Magieschaden 5 Min. lang um 5% erhöht wird.\n\nFlüche\nEs kann pro Ziel immer nur jeweils ein Fluch des Hexenmeisters aktiv sein. [ Seelenbrand: Fluch : Seelenbrand:\nEuer Zauber 'Fluch der Elemente' trifft alle Gegner im Umkreis von 10 Metern um Euer Ziel. ]" }
entries[104230] = { ["name"] = "Zwielichtatem", ["text"] = "Unbegrenzte Reichweite\nSofort\nAtmet einen Storm Zwielichtenergie in Richtung des Ziels aus." }
entries[104232] = { ["name"] = "Feuerregen", ["text"] = "25% von Grundmana 35 Meter Reichweite\nSofort\nLässt einen feurigen Regen niedergehen, der Gegnern im Effektbereich im Verlauf von 8 Sek. insgesamt ( 160 * 8) Feuerschaden zufügt.\n\nVerursacht 50% mehr Schaden, wenn das Ziel von 'Feuerbrand' betroffen ist." }
entries[104233] = { ["name"] = "Feuerregen", ["text"] = "Unbegrenzte Reichweite\nSofort\nLässt einen feurigen Regen niedergehen, der Gegnern im Effektbereich im Verlauf von 8 Sek. insgesamt ( 160 * 8) Feuerschaden zufügt.\n\nVerursacht 50% mehr Schaden, wenn das Ziel von 'Feuerbrand' betroffen ist." }
