entries[104236] = { ["name"] = "Kiryns Ho-zen-Gift", ["text"] = "100 Meter Reichweite\nSofort\nEine Dosis von einem speziell für Ho-zen bestimmtem Gift, dass selbst den Stärksten von ihnen schwächt." }
